import {
  mergeVariantReferences,
  type VariantReference,
} from '../types/variant-reference';
import crypto from 'crypto';
import fs from 'fs';
import os from 'os';
import path from 'path';
import {
  type RawUserContextInput,
  type ContextAssetInput,
  type StoredUserContextSourceRecord,
  type VariantContextBundle,
  type VariantWorkItemContext,
  variantContextBundleSchema,
} from './contracts';
import { AgentVariantsError } from './errors';
import { isPathWithinRoot } from '../utils/pathContainment';
import { normalizeUrl } from './sourceContext';
import { stageContextAssets } from './contextAssets';

export const USER_CONTEXT_DIRECTORY = 'user';
const METADATA_DIRECTORY = 'metadata';
const CONTEXT_FILE = 'context.json';
const PROMPT_FILE = 'prompt.md';
const MAX_FILE_CONTEXT_BYTES = 50 * 1024 * 1024;
const UPLOAD_DATA_URL_PATTERN = /^data:([^;,]+);base64,(.*)$/s;
const BASE64_PAYLOAD_PATTERN = /^[A-Za-z0-9+/=\s]+$/;
const SUPPORTED_UPLOAD_IMAGE_EXTENSIONS = new Map([
  ['image/png', 'png'],
  ['image/jpeg', 'jpg'],
  ['image/webp', 'webp'],
  ['image/gif', 'gif'],
  ['image/avif', 'avif'],
]);

type CreateVariantContextBundleArgs = {
  sessionId: string;
  prompt: string;
  workspaceRoot: string;
  dataDirectory?: string;
  sourceUrls?: string[];
  userContextInputs?: RawUserContextInput[];
  profileContextInputs?: RawUserContextInput[];
  allowedRoots?: string[];
  contextAssets?: ContextAssetInput[];
};

type SourceContextSelection = {
  source?: VariantWorkItemContext;
  sourceReferenceMetadata?: VariantReference[];
  profileReferenceMode?: 'inherit' | 'replace';
};

type VariantContextManifest = VariantContextBundle & {
  storedUserContext: StoredUserContextSourceRecord[];
};

const ensureDir = (dir: string): void => {
  fs.mkdirSync(dir, { recursive: true });
};

const writeTextFile = (filePath: string, content: string): void => {
  ensureDir(path.dirname(filePath));
  fs.writeFileSync(filePath, content, 'utf8');
};

const sha256File = (filePath: string): string => {
  const hash = crypto.createHash('sha256');
  hash.update(fs.readFileSync(filePath));
  return hash.digest('hex');
};

const safeNamePart = (value: string | undefined, fallback: string): string => {
  const base = (value ?? fallback)
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
  return base || fallback;
};

const realpathIfPresent = (candidate: string): string | null => {
  try {
    return fs.realpathSync(candidate);
  } catch {
    return null;
  }
};

const isBroadAllowedRoot = (root: string): boolean => {
  const resolvedRoot = path.resolve(root);
  const filesystemRoot = path.parse(resolvedRoot).root;
  const homeRoot =
    realpathIfPresent(os.homedir()) ?? path.resolve(os.homedir());
  const tempRoot = realpathIfPresent(os.tmpdir()) ?? path.resolve(os.tmpdir());
  return (
    resolvedRoot === filesystemRoot ||
    resolvedRoot === homeRoot ||
    resolvedRoot === tempRoot
  );
};

const resolveAllowedRoots = (roots: string[]): string[] =>
  roots
    .map((root) => realpathIfPresent(root))
    .filter((root): root is string => {
      if (!root) return false;
      return !isBroadAllowedRoot(root);
    });

export const readStoredUserContext = (
  contextBundlePath: string,
): StoredUserContextSourceRecord[] | undefined => {
  const manifestPath = path.join(contextBundlePath, CONTEXT_FILE);
  try {
    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8')) as {
      storedUserContext?: StoredUserContextSourceRecord[];
    };
    if (!Array.isArray(manifest.storedUserContext)) return undefined;
    return manifest.storedUserContext;
  } catch {
    return undefined;
  }
};

const assertAllowedPath = (
  sourcePath: string,
  allowedRoots: string[],
): string => {
  const resolvedPath = realpathIfPresent(sourcePath);
  if (!resolvedPath) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      `User context path is not readable: ${sourcePath}`,
    );
  }
  const isAllowed = allowedRoots.some((root) =>
    isPathWithinRoot(root, resolvedPath),
  );
  if (!isAllowed) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      `User context path escapes the allowed roots: ${sourcePath}`,
    );
  }
  return resolvedPath;
};

const copyFileSource = (args: {
  input: Extract<RawUserContextInput, { transport: 'file_path' }>;
  id: string;
  userDir: string;
  allowedRoots: string[];
}): StoredUserContextSourceRecord => {
  const sourcePath = assertAllowedPath(args.input.path, args.allowedRoots);
  const stat = fs.statSync(sourcePath);
  if (!stat.isFile()) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      `User context file path is not a regular file: ${args.input.path}`,
    );
  }
  if (stat.size > MAX_FILE_CONTEXT_BYTES) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_TOO_LARGE',
      `User context file exceeds size limit (${stat.size} > ${MAX_FILE_CONTEXT_BYTES})`,
    );
  }

  const originalFilename = path.basename(sourcePath);
  const filename = `${args.id}-${safeNamePart(originalFilename, 'file')}`;
  const destination = path.join(args.userDir, filename);
  fs.copyFileSync(sourcePath, destination);

  return {
    source: {
      id: args.id,
      transport: 'file',
      origin: 'user',
      path: destination,
      ...(args.input.mimeType ? { mimeType: args.input.mimeType } : {}),
      originalFilename,
      ...(args.input.label ? { label: args.input.label } : {}),
      ...(args.input.userIntent ? { userIntent: args.input.userIntent } : {}),
    },
    storage: {
      sizeBytes: stat.size,
      sha256: sha256File(destination),
      originalFilename,
    },
  };
};

const decodeUploadDataUrl = (
  dataUrl: string,
): {
  buffer: Buffer;
  mimeType: string;
  extension: string;
} => {
  const match = dataUrl.match(UPLOAD_DATA_URL_PATTERN);
  if (!match) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      'Uploaded user context must be a base64 data URL.',
    );
  }

  const mimeType = match[1].toLowerCase().trim();
  const extension = SUPPORTED_UPLOAD_IMAGE_EXTENSIONS.get(mimeType);
  if (!extension) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      `Unsupported uploaded user context MIME type: ${mimeType}`,
    );
  }

  const base64Data = match[2].replace(/\s+/g, '');
  if (!base64Data || !BASE64_PAYLOAD_PATTERN.test(base64Data)) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      'Uploaded user context contains invalid base64 data.',
    );
  }

  const buffer = Buffer.from(base64Data, 'base64');
  if (buffer.length === 0) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      'Uploaded user context is empty.',
    );
  }
  if (buffer.length > MAX_FILE_CONTEXT_BYTES) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_TOO_LARGE',
      `Uploaded user context exceeds size limit (${buffer.length} > ${MAX_FILE_CONTEXT_BYTES})`,
    );
  }

  return { buffer, mimeType, extension };
};

const copyUploadSource = (args: {
  input: Extract<RawUserContextInput, { transport: 'upload' }>;
  origin: 'user' | 'profile';
  id: string;
  userDir: string;
}): StoredUserContextSourceRecord => {
  const upload = decodeUploadDataUrl(args.input.dataUrl);
  const originalFilename = args.input.filename;
  const nameSource = originalFilename
    ? path.parse(originalFilename).name
    : args.input.label;
  const filename = `${args.id}-${safeNamePart(nameSource, 'upload')}.${upload.extension}`;
  const destination = path.join(args.userDir, filename);
  ensureDir(path.dirname(destination));
  fs.writeFileSync(destination, upload.buffer);

  return {
    source: {
      id: args.id,
      transport: 'file',
      origin: args.origin,
      path: destination,
      mimeType: upload.mimeType,
      references: mergeVariantReferences(args.input.references),
      ...(originalFilename ? { originalFilename } : {}),
      ...(args.input.label ? { label: args.input.label } : {}),
      ...(args.input.userIntent ? { userIntent: args.input.userIntent } : {}),
    },
    storage: {
      sizeBytes: upload.buffer.length,
      sha256: sha256File(destination),
      ...(originalFilename ? { originalFilename } : {}),
    },
  };
};

const createTextSource = (args: {
  id: string;
  userDir: string;
  label: string | undefined;
  userIntent: string | undefined;
  content: string;
  fallbackName: string;
  origin: 'user' | 'profile';
  references?: VariantReference[];
}): StoredUserContextSourceRecord => {
  const filename = `${args.id}-${safeNamePart(args.label, args.fallbackName)}.md`;
  const textPath = path.join(args.userDir, filename);
  writeTextFile(textPath, `${args.content.trim()}\n`);
  return {
    source: {
      id: args.id,
      transport: 'text',
      origin: args.origin,
      path: textPath,
      references: mergeVariantReferences(args.references),
      ...(args.label ? { label: args.label } : {}),
      ...(args.userIntent ? { userIntent: args.userIntent } : {}),
    },
    storage: {
      sizeBytes: Buffer.byteLength(args.content, 'utf8'),
      sha256: sha256File(textPath),
    },
  };
};

const applyUrlSourceDetails = (
  record: StoredUserContextSourceRecord,
  details: { label?: string; userIntent?: string },
): void => {
  if (record.source.transport !== 'url') return;
  if (details.label && !record.source.label) {
    record.source.label = details.label;
  }
  if (details.userIntent && !record.source.userIntent) {
    record.source.userIntent = details.userIntent;
  }
};

export const createVariantContextBundle = (
  args: CreateVariantContextBundleArgs,
): VariantContextBundle => {
  const contextBundlePath = path.join(
    args.dataDirectory ?? path.join(args.workspaceRoot, '.rivet'),
    'variant-context',
    args.sessionId,
  );
  const userDir = path.join(contextBundlePath, USER_CONTEXT_DIRECTORY);
  ensureDir(userDir);
  ensureDir(path.join(contextBundlePath, METADATA_DIRECTORY));

  const allowedRoots = resolveAllowedRoots([...(args.allowedRoots ?? [])]);
  const storedUserContext: StoredUserContextSourceRecord[] = [];
  const promptPath = path.join(userDir, PROMPT_FILE);
  writeTextFile(promptPath, `${args.prompt.trim()}\n`);
  storedUserContext.push({
    source: {
      id: 'uc_prompt_1',
      transport: 'prompt',
      path: promptPath,
    },
    storage: {
      sizeBytes: Buffer.byteLength(args.prompt, 'utf8'),
      sha256: sha256File(promptPath),
    },
  });

  const urlRecordsByUrl = new Map<string, StoredUserContextSourceRecord>();
  const addUrlSource = (args: {
    id: string;
    url: string;
    label?: string;
    userIntent?: string;
    isRequired?: boolean;
  }): boolean => {
    const normalized = normalizeUrl(args.url);
    if (!normalized) {
      if (args.isRequired) {
        throw new AgentVariantsError(
          'SOURCE_CONTEXT_INVALID',
          `Invalid user context URL: ${args.url}`,
        );
      }
      return false;
    }

    const existingRecord = urlRecordsByUrl.get(normalized);
    if (existingRecord) {
      applyUrlSourceDetails(existingRecord, {
        label: args.label,
        userIntent: args.userIntent,
      });
      return true;
    }

    const record: StoredUserContextSourceRecord = {
      source: {
        id: args.id,
        transport: 'url',
        url: normalized,
        ...(args.label ? { label: args.label } : {}),
        ...(args.userIntent ? { userIntent: args.userIntent } : {}),
      },
    };
    urlRecordsByUrl.set(normalized, record);
    storedUserContext.push(record);
    return true;
  };

  let urlIndex = 0;
  for (const url of args.sourceUrls ?? []) {
    const isUrlSourceAccepted = addUrlSource({
      id: `uc_url_${urlIndex + 1}`,
      url,
    });
    if (isUrlSourceAccepted) {
      urlIndex += 1;
    }
  }

  let extraIndex = 0;
  for (const input of [
    ...(args.userContextInputs ?? []),
    ...(args.profileContextInputs ?? []),
  ]) {
    const origin =
      extraIndex < (args.userContextInputs?.length ?? 0) ? 'user' : 'profile';
    extraIndex += 1;
    if (input.transport === 'url') {
      addUrlSource({
        id: `uc_input_${extraIndex}`,
        url: input.url,
        label: input.label,
        userIntent: input.userIntent,
        isRequired: true,
      });
    } else if (input.transport === 'text') {
      storedUserContext.push(
        createTextSource({
          id: `uc_input_${extraIndex}`,
          userDir,
          label: input.label,
          userIntent: input.userIntent,
          content: input.content,
          origin,
          references: input.references,
          fallbackName: `input-${extraIndex}`,
        }),
      );
    } else if (input.transport === 'file_path') {
      storedUserContext.push(
        copyFileSource({
          input,
          id: `uc_input_${extraIndex}`,
          userDir,
          allowedRoots,
        }),
      );
    } else if (input.transport === 'upload') {
      storedUserContext.push(
        copyUploadSource({
          input,
          origin,
          id: `uc_input_${extraIndex}`,
          userDir,
        }),
      );
    } else {
      const sourcePath = assertAllowedPath(input.path, allowedRoots);
      if (!fs.statSync(sourcePath).isDirectory()) {
        throw new AgentVariantsError(
          'SOURCE_CONTEXT_INVALID',
          `User context directory path is not a directory: ${input.path}`,
        );
      }
      storedUserContext.push({
        source: {
          id: `uc_input_${extraIndex}`,
          transport: 'directory',
          path: sourcePath,
          ...(input.label ? { label: input.label } : {}),
          ...(input.userIntent ? { userIntent: input.userIntent } : {}),
        },
      });
    }
  }

  const bundle: VariantContextBundle = {
    version: 1,
    sessionId: args.sessionId,
    contextBundlePath,
    userContext: storedUserContext.map((entry) => entry.source),
    rivetActions: [],
    rivetMetadata: [],
    ...(args.contextAssets?.length
      ? {
          contextAssets: stageContextAssets({
            assets: args.contextAssets,
            contextBundlePath,
          }),
        }
      : {}),
  };
  writeVariantContextBundle(bundle, storedUserContext);
  return bundle;
};

export const writeVariantContextBundle = (
  bundle: VariantContextBundle,
  storedUserContext?: StoredUserContextSourceRecord[],
): void => {
  ensureDir(bundle.contextBundlePath);
  const manifest: VariantContextManifest = {
    ...bundle,
    storedUserContext:
      storedUserContext ??
      readStoredUserContext(bundle.contextBundlePath) ??
      bundle.userContext.map((source) => ({
        source,
      })),
  };
  fs.writeFileSync(
    path.join(bundle.contextBundlePath, CONTEXT_FILE),
    `${JSON.stringify(manifest, null, 2)}\n`,
    'utf8',
  );
};

const retainedContextSources = (args: SourceContextSelection) =>
  (args.source?.userContext ?? []).filter(
    (source) =>
      args.profileReferenceMode !== 'replace' ||
      !('origin' in source) ||
      source.origin !== 'profile',
  );

export const retainedReferenceMetadata = (args: SourceContextSelection) =>
  mergeVariantReferences(
    args.profileReferenceMode === 'replace'
      ? undefined
      : args.source?.references,
    args.profileReferenceMode === 'replace'
      ? undefined
      : args.sourceReferenceMetadata,
    ...retainedContextSources(args).map((source) =>
      'references' in source ? source.references : undefined,
    ),
  );

export const extendVariantContextBundle = (
  args: SourceContextSelection & {
    sessionId: string;
    additional: Pick<
      VariantWorkItemContext,
      'contextBundlePath' | 'userContext' | 'rivetMetadata'
    >;
  },
): typeof args.additional & Pick<VariantWorkItemContext, 'references'> => {
  let inherited: VariantContextBundle | undefined;
  try {
    inherited = args.source
      ? variantContextBundleSchema.parse(
          JSON.parse(
            fs.readFileSync(
              path.join(args.source.contextBundlePath, CONTEXT_FILE),
              'utf8',
            ),
          ),
        )
      : undefined;
  } catch {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      'Cannot read the source design context. Recreate the direction before varying it.',
    );
  }
  const inheritedSources = args.source?.userContext ?? [];
  const inheritedReferences = mergeVariantReferences(
    args.source?.references,
    args.sourceReferenceMetadata,
  );
  const retainedReferenceIds = new Set(
    inheritedSources.flatMap((source) =>
      'references' in source
        ? (source.references ?? []).map((reference) => reference.id)
        : [],
    ),
  );
  if (
    args.profileReferenceMode === 'replace' &&
    (inheritedReferences?.some(
      (reference) => !retainedReferenceIds.has(reference.id),
    ) ||
      inheritedSources.some(
        (source) =>
          (source.transport === 'file' || source.transport === 'text') &&
          !source.origin,
      ))
  ) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      'Cannot replace saved references because this direction has no retained reference ownership. Recreate the direction with the desired references before varying it.',
    );
  }
  const retainedSources = retainedContextSources(args);
  const removedSourceIds = new Set(
    inheritedSources
      .filter((source) => !retainedSources.includes(source))
      .map((source) => source.id),
  );
  const sourceIds = new Set(retainedSources.map((source) => source.id));
  const additionalIds = new Map(
    args.additional.userContext.map((source) => [
      source.id,
      sourceIds.has(source.id)
        ? `${crypto.randomUUID()}_${source.id}`
        : source.id,
    ]),
  );
  const rivetMetadata = [
    ...(args.source?.rivetMetadata ?? []).filter(
      (metadata) => !metadata.sourceIds.some((id) => removedSourceIds.has(id)),
    ),
    ...args.additional.rivetMetadata.map((metadata) => ({
      ...metadata,
      sourceIds: metadata.sourceIds.map((id) => additionalIds.get(id) ?? id),
    })),
  ];
  const contextBundlePath = path.join(
    args.additional.contextBundlePath,
    crypto.randomUUID(),
  );
  const records = [
    ...(args.source
      ? (readStoredUserContext(args.source.contextBundlePath) ?? []).filter(
          ({ source }) =>
            retainedSources.some(
              (retained) =>
                source.transport === retained.transport &&
                ('path' in source && 'path' in retained
                  ? source.path === retained.path
                  : source.id === retained.id),
            ),
        )
      : []),
    ...(readStoredUserContext(args.additional.contextBundlePath) ?? []),
  ];
  const imagePathsByHash = new Map<string, string>();
  const imagePaths = new Map<string, string>();
  for (const { source, storage } of records) {
    if (
      source.transport !== 'file' ||
      !source.mimeType?.startsWith('image/') ||
      !storage?.sha256
    )
      continue;
    const imagePath = imagePathsByHash.get(storage.sha256) ?? source.path;
    imagePathsByHash.set(storage.sha256, imagePath);
    imagePaths.set(source.path, imagePath);
  }
  const additionalUserContext = args.additional.userContext.map((source) =>
    source.transport === 'file' && imagePaths.has(source.path)
      ? { ...source, path: imagePaths.get(source.path) ?? source.path }
      : source,
  );
  const userContext = [
    ...retainedSources,
    ...additionalUserContext.map((source) => ({
      ...source,
      id: additionalIds.get(source.id) ?? source.id,
    })),
  ];
  writeVariantContextBundle(
    {
      ...inherited,
      version: 1,
      sessionId: args.sessionId,
      contextBundlePath,
      userContext,
      rivetActions: inherited?.rivetActions ?? [],
      rivetMetadata,
      ...(args.source?.contextAssets
        ? { contextAssets: args.source.contextAssets }
        : {}),
    },
    userContext.map((source) => {
      const record = records.find(
        (entry) =>
          entry.source.transport === source.transport &&
          ('path' in source && 'path' in entry.source
            ? source.path === entry.source.path
            : entry.source.id === source.id),
      );
      return { ...record, source };
    }),
  );
  return {
    ...args.additional,
    references: mergeVariantReferences(
      retainedReferenceMetadata(args),
      ...additionalUserContext.map((source) =>
        'references' in source ? source.references : undefined,
      ),
    ),
    contextBundlePath,
    userContext,
    rivetMetadata,
  };
};
